} from '@ng-icons/lucide';
import { AiService, GeneratedResource, KnowledgeGap, QuizQuestion } from '../../services/ai.service';
import { MarkdownPipe } from '../../pipes/markdown.pipe';
import { SidebarComponent } from '../sidebar/sidebar.component';
import { ConfirmDialogComponent } from '../confirm-dialog/confirm-dialog.component';

type Phase = 'config' | 'exam' | 'results';
type Difficulty = 'BEGINNER' | 'INTERMEDIATE' | 'ADVANCED';

interface ExamResult {
  score: number;
  correct: number;
  total: number;
  secondsUsed: number;
}

const DURATIONS = [10, 20, 30, 45];
const COUNTS = [5, 8, 10, 15];

@Component({
  selector: 'app-simulacro',
  standalone: true,
  imports: [DatePipe, FormsModule, NgIconComponent, MarkdownPipe, SidebarComponent, ConfirmDialogComponent],
  providers: [
    provideIcons({
      lucideCheckCircle2, lucideChevronLeft, lucideChevronRight, lucideClock, lucideFlag,
      lucideHistory, lucideLoader, lucidePlay, lucideRotateCcw, lucideSparkles, lucideTarget,
      lucideTimer, lucideTrophy, lucideXCircle,
    }),
  ],
  templateUrl: './simulacro.component.html',
  styles: [`
    .exam-q p { margin: 0 0 0.5em 0; }
    .exam-q p:last-child { margin-bottom: 0; }
    .exam-q ul, .exam-q ol { margin: 0.25em 0; padding-left: 1.5em; }
    .exam-q strong { font-weight: 700; }
    .exam-q em { font-style: italic; }
    .exam-q .katex { font-size: 1.05em; }
    .exam-opt { line-height: 1.55; }
    .exam-opt p { margin: 0; }
    .exam-opt .katex { font-size: 1.05em; }
  `],
})
export class SimulacroComponent implements OnInit, OnDestroy {
  protected ai = inject(AiService);

  readonly durations = DURATIONS;
  readonly counts = COUNTS;

  phase = signal<Phase>('config');

  // ── Configuración ────────────────────────────────
  topic = signal('');
  difficulty = signal<Difficulty>('INTERMEDIATE');
  count = signal(8);
  durationMin = signal(20);
  generating = signal(false);
  error = signal<string | null>(null);

  gaps = signal<KnowledgeGap[]>([]);
  loadingGaps = signal(true);

  // ── Examen ───────────────────────────────────────
  quiz = signal<GeneratedResource | null>(null);
  answers = signal<(number | null)[]>([]);
  qIndex = signal(0);
  secondsLeft = signal(0);
  timeUp = signal(false);
  showFinishConfirm = signal(false);
  private timer: ReturnType<typeof setInterval> | null = null;

  // ── Resultados ───────────────────────────────────
  result = signal<ExamResult | null>(null);
  savingResult = signal(false);

  // ── Historial ────────────────────────────────────
  history = signal<GeneratedResource[]>([]);
  loadingHistory = signal(true);

  questions = computed<QuizQuestion[]>(() => this.quiz()?.content?.quiz || []);
  currentQuestion = computed<QuizQuestion | null>(() => this.questions()[this.qIndex()] ?? null);
  answeredCount = computed(() => this.answers().filter(a => a !== null).length);
  allAnswered = computed(() => this.questions().length > 0 && this.answeredCount() === this.questions().length);
  timeLabel = computed(() => {
    const total = Math.max(0, this.secondsLeft());
    const m = Math.floor(total / 60);
    const s = total % 60;
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  });
  timeProgress = computed(() => {
    const total = this.durationMin() * 60;
    return total > 0 ? Math.max(0, Math.min(100, (this.secondsLeft() / total) * 100)) : 0;
  });
  timeLow = computed(() => this.secondsLeft() <= 60);
  durationLabel = computed(() => `${this.durationMin()} min`);

  attempts = computed(() => this.history().filter(r => r.completed && typeof r.resultScore === 'number'));
  bestScore = computed(() => {
    const rows = this.attempts();
    return rows.length ? Math.max(...rows.map(r => r.resultScore || 0)) : null;
  });
  averageScore = computed(() => {
    const rows = this.attempts();
    if (!rows.length) return null;
    return Math.round(rows.reduce((sum, r) => sum + (r.resultScore || 0), 0) / rows.length);
  });

  ngOnInit(): void {
    this.loadGaps();
    this.loadHistory();
  }

  ngOnDestroy(): void {
    this.stopTimer();
  }

  // ── Datos ────────────────────────────────────────
  private loadGaps(): void {
    this.ai.getKnowledgeGaps().subscribe({
      next: (res) => {
        this.gaps.set((res.gaps || []).slice(0, 6));
        this.loadingGaps.set(false);
      },
      error: () => this.loadingGaps.set(false),
    });
  }

  loadHistory(): void {
    this.loadingHistory.set(true);
    this.ai.getResources('QUIZ', true).subscribe({
      next: (res) => {
        this.history.set(res.resources || []);
        this.loadingHistory.set(false);
      },
      error: () => this.loadingHistory.set(false),
    });
  }

  // ── Configuración ────────────────────────────────
  pickGap(topic: string): void {
    this.topic.set(this.topic() === topic ? '' : topic);
  }

  setDifficulty(level: Difficulty): void {
    this.difficulty.set(level);
  }

  setCount(value: number): void {
    this.count.set(value);
  }

  setDuration(value: number): void {
    this.durationMin.set(value);
  }

  startExam(): void {
    if (this.generating()) return;
    this.error.set(null);
    this.generating.set(true);
    const topic = this.topic().trim() || undefined;
    this.ai.generateQuiz({ topic, difficulty: this.difficulty(), count: this.count() }).subscribe({
      next: (res) => {
        this.generating.set(false);
        const questions = res.resource?.content?.quiz || [];
        if (!questions.length) {
          this.error.set('La IA no devolvió preguntas. Prueba con otro tema o dificultad.');
          return;
        }
        this.quiz.set(res.resource);
        this.answers.set(new Array(questions.length).fill(null));
        this.qIndex.set(0);
        this.result.set(null);
        this.timeUp.set(false);
        this.phase.set('exam');
        this.startTimer();
      },
      error: () => {
        this.generating.set(false);
        this.error.set('No se pudo generar el simulacro. Revisa tu conexión e inténtalo de nuevo.');
      },
    });
  }

  // ── Cronómetro ───────────────────────────────────
  private startTimer(): void {
    this.stopTimer();
    this.secondsLeft.set(this.durationMin() * 60);
    this.timer = setInterval(() => {
      const left = this.secondsLeft() - 1;
      this.secondsLeft.set(left);
      if (left <= 0) this.submit(true);
    }, 1000);
  }

  private stopTimer(): void {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  // ── Examen ───────────────────────────────────────
  selectAnswer(optionIndex: number): void {
    if (this.phase() !== 'exam') return;
    const next = [...this.answers()];
    next[this.qIndex()] = optionIndex;
    this.answers.set(next);
  }

  nextQuestion(): void {
    if (this.qIndex() < this.questions().length - 1) this.qIndex.update(i => i + 1);
  }

  previousQuestion(): void {
    if (this.qIndex() > 0) this.qIndex.update(i => i - 1);
  }

  goToQuestion(index: number): void {
    this.qIndex.set(index);
  }

  optionLetter(index: number): string {
    return String.fromCharCode(65 + index);
  }

  correctIndexOf(question: QuizQuestion | null): number {
    if (!question) return -1;
    const answer = (question.answer || '').trim();
    return (question.choices || []).findIndex(c => (c || '').trim() === answer);
  }

  requestFinish(): void {
    if (this.allAnswered()) {
      this.submit(false);
      return;
    }
    this.showFinishConfirm.set(true);
  }

  confirmFinish(): void {
    this.showFinishConfirm.set(false);
    this.submit(false);
  }

  cancelFinish(): void {
    this.showFinishConfirm.set(false);
  }

  isCorrect(index: number): boolean {
    const question = this.questions()[index];
    return this.answers()[index] !== null && this.answers()[index] === this.correctIndexOf(question);
  }

  private submit(auto: boolean): void {
    if (this.phase() !== 'exam') return;
    const questions = this.questions();
    if (!questions.length) return;
    this.stopTimer();
    this.timeUp.set(auto);

    let correct = 0;
    questions.forEach((question, index) => {
      if (this.answers()[index] === this.correctIndexOf(question)) correct++;
    });
    const total = questions.length;
    const secondsUsed = Math.max(0, this.durationMin() * 60 - this.secondsLeft());

    this.result.set({
      score: Math.round((correct / total) * 100),
      correct,
      total,
      secondsUsed,
    });
    this.phase.set('results');

    const quiz = this.quiz();
    if (quiz) {
      this.savingResult.set(true);
      this.ai.completeResource(quiz.id, {
        resultScore: Math.round((correct / total) * 100),
        resultCorrect: correct,
        resultTotal: total,
      }).subscribe({
        next: () => {
          this.savingResult.set(false);
          this.loadHistory();
        },
        error: () => this.savingResult.set(false),
      });
    }
  }

  // ── Resultados ───────────────────────────────────
  formatSeconds(total: number): string {
    const m = Math.floor(total / 60);
    const s = total % 60;
    return `${m}m ${String(s).padStart(2, '0')}s`;
  }

  scoreLabel(score: number | null | undefined): string {
    if (score === null || score === undefined) return '—';
    if (score >= 80) return 'Excelente';
    if (score >= 60) return 'Aprobado';
    return 'A repasar';
  }

  retakeExam(): void {
    if (!this.quiz()) return;
    this.answers.set(new Array(this.questions().length).fill(null));
    this.qIndex.set(0);
    this.result.set(null);
    this.timeUp.set(false);
    this.phase.set('exam');
    this.startTimer();
  }

  newExam(): void {
    this.stopTimer();
    this.quiz.set(null);
    this.result.set(null);
    this.error.set(null);
    this.phase.set('config');
    this.loadGaps();
  }
}
