          <div class="mb-6">
            <label class="block text-sm font-semibold mb-2" style="color: #061E24;">Dificultad</label>
            <div class="flex flex-wrap gap-2">
              @for (level of ['BEGINNER', 'INTERMEDIATE', 'ADVANCED']; track level) {
                <button (click)="setDifficulty($any(level))"
                  class="px-4 py-2 rounded-full text-sm font-medium border transition-colors"
                  [class]="difficulty() === level
                    ? 'bg-[#0C5A60] text-white border-[#0C5A60]'
                    : 'bg-white text-gray-600 border-gray-200 hover:border-[#0C5A60]'">
