          } @else {
            <div class="flex flex-wrap gap-3 mb-6">
              <div class="px-4 py-2.5 rounded-xl border border-gray-100" style="background: #f8fafc;">
                <p class="text-xs text-gray-400 font-medium">Intentos</p>
                <p class="text-lg font-bold" style="color: #061E24;">{{ attempts().length }}</p>
              </div>
              <div class="px-4 py-2.5 rounded-xl border border-gray-100" style="background: #f8fafc;">
                <p class="text-xs text-gray-400 font-medium">Mejor nota</p>
                <p class="text-lg font-bold" style="color: #0C5A60;">{{ bestScore() }}</p>
              </div>
              <div class="px-4 py-2.5 rounded-xl border border-gray-100" style="background: #f8fafc;">
                <p class="text-xs text-gray-400 font-medium">Promedio</p>
                <p class="text-lg font-bold" style="color: #061E24;">{{ averageScore() }}</p>
              </div>
            </div>

            <div class="flex flex-col gap-3">
              @for (attempt of attempts(); track attempt.id) {
                <div class="flex items-center justify-between gap-4 px-4 py-3 rounded-xl border border-gray-100">
                  <div class="min-w-0">
                    <p class="text-sm font-semibold truncate" style="color: #061E24;">{{ attempt.title }}</p>
                    <p class="text-xs text-gray-400 mt-0.5">
                      {{ (attempt.completedAt || attempt.createdAt) | date:'dd/MM/yyyy HH:mm' }}
                      · {{ attempt.resultCorrect }}/{{ attempt.resultTotal }} correctas
                    </p>
                  </div>
                  <span class="shrink-0 px-3 py-1.5 rounded-full text-sm font-bold"
                    [style.background]="(attempt.resultScore || 0) >= 80 ? '#ecfdf5' : (attempt.resultScore || 0) >= 60 ? '#fffbeb' : '#fef2f2'"
                    [style.color]="(attempt.resultScore || 0) >= 80 ? '#047857' : (attempt.resultScore || 0) >= 60 ? '#b45309' : '#b91c1c'">
                    {{ attempt.resultScore }}
                  </span>
                </div>
              }
            </div>
          }
        </div>
      }

      <!-- ════════════ EXAMEN ════════════ -->
      @if (phase() === 'exam') {
        <div class="bg-white rounded-2xl shadow-sm border border-gray-100 px-5 py-4 mb-5 sticky top-0 z-10">
          <div class="flex items-center justify-between gap-4 mb-3">
            <div class="flex items-center gap-3">
              <ng-icon name="lucideTimer" size="20" [color]="timeLow() ? '#b91c1c' : '#0C5A60'" />
              <div>
                <p class="text-2xl font-bold tracking-tight tabular-nums" [style.color]="timeLow() ? '#b91c1c' : '#061E24'">{{ timeLabel() }}</p>
                <p class="text-xs text-gray-400">{{ durationLabel() }} · {{ answeredCount() }}/{{ questions().length }} respondidas</p>
              </div>
            </div>
            <button (click)="requestFinish()"
              class="px-5 py-2.5 rounded-xl text-sm font-semibold text-white flex items-center gap-2 transition-colors"
              style="background: #b45309;">
              <ng-icon name="lucideFlag" size="15" />
              Entregar
