                    {{ optionLetter($index) }}
                  </span>
                  <span class="text-sm leading-relaxed exam-opt" style="color: #1e293b;" [innerHTML]="choice | markdown"></span>
                </button>
              }
            </div>

            <div class="flex items-center justify-between gap-3 mt-7">
              <button (click)="previousQuestion()" [disabled]="qIndex() === 0"
                class="px-4 py-2.5 rounded-xl text-sm font-semibold border border-gray-200 text-gray-600 flex items-center gap-1.5 disabled:opacity-40 hover:border-[#0C5A60] transition-colors">
                <ng-icon name="lucideChevronLeft" size="15" />
                Anterior
