                  class="px-5 py-2.5 rounded-xl text-sm font-semibold text-white flex items-center gap-1.5 transition-colors"
                  style="background: #0C5A60;">
                  <ng-icon name="lucideFlag" size="15" />
                  Entregar examen
                </button>
              }
            </div>
          </div>
        }
      }

      <!-- ════════════ RESULTADOS ════════════ -->
      @if (phase() === 'results') {
        @if (result(); as res) {
          <div class="bg-white rounded-3xl shadow-sm border border-gray-100 p-5 sm:p-8 mb-6">
            <div class="flex flex-col sm:flex-row items-center gap-6">
              <div class="w-32 h-32 rounded-full flex flex-col items-center justify-center shrink-0"
