                  </p>
                }
              </div>
              <div class="sm:ml-auto flex flex-col gap-2 w-full sm:w-auto">
                <button (click)="retakeExam()"
                  class="px-5 py-2.5 rounded-xl text-sm font-semibold text-white flex items-center justify-center gap-2 transition-colors"
                  style="background: #0C5A60;">
                  <ng-icon name="lucideRotateCcw" size="15" />
                  Repetir este examen
                </button>
                <button (click)="newExam()"
                  class="px-5 py-2.5 rounded-xl text-sm font-semibold border border-gray-200 text-gray-600 flex items-center justify-center gap-2 hover:border-[#0C5A60] transition-colors">
                  <ng-icon name="lucideSparkles" size="15" />
                  Nuevo simulacro
                </button>
              </div>
            </div>
          </div>

