          <div class="bg-white rounded-3xl shadow-sm border border-gray-100 p-5 sm:p-8">
            <h3 class="text-lg font-bold mb-5" style="color: #061E24;">Revisión de respuestas</h3>

            <div class="flex flex-col gap-5">
              @for (question of questions(); track $index) {
                <div class="border-b border-gray-100 pb-5 last:border-0 last:pb-0">
                  <div class="flex items-start gap-3">
                    <span class="w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold shrink-0 mt-0.5"
                      [style.background]="answers()[$index] === null ? '#f1f5f9' : (isCorrect($index) ? '#ecfdf5' : '#fef2f2')"
                      [style.color]="answers()[$index] === null ? '#64748b' : (isCorrect($index) ? '#047857' : '#b91c1c')">
                      {{ $index + 1 }}
                    </span>
                    <div class="min-w-0 flex-1">
                      <div class="text-sm font-medium mb-2 leading-relaxed exam-q" style="color: #061E24;">
                        <span [innerHTML]="question.question | markdown"></span>
                      </div>

                      @if (answers()[$index] === null) {
                        <p class="text-xs font-semibold mb-1" style="color: #64748b;">Sin responder</p>
