  get questions(): QuizQuestion[] { return this.activeQuiz()?.content?.quiz ?? []; }
  get currentQuestion(): QuizQuestion | null { return this.questions[this.currentIndex()] ?? null; }
  get answeredCount(): number { return Object.keys(this.answers()).length; }
  get progressPct(): number { const t = this.questions.length; return t ? Math.round((this.answeredCount / t) * 100) : 0; }
  get timePct(): number { const t = this.totalTime(); return t ? Math.max(0, (this.timeLeft() / t) * 100) : 100; }
  get timeCritical(): boolean { return this.timeLeft() <= Math.max(30, this.totalTime() * 0.15); }
  get timeUsedSeconds(): number { return Math.max(0, this.totalTime() - this.timeLeft()); }
  get elapsedLabel(): string { return this.formatTime(this.timeUsedSeconds); }
  get remainingLabel(): string { return this.formatTime(this.timeLeft()); }
  get correctCount(): number {
    const answers = this.answers();
    return this.questions.reduce((acc, q, i) => acc + (answers[i] !== undefined && answers[i] === this.correctIndexOf(q) ? 1 : 0), 0);
  }
  get wrongCount(): number { ... answers[i] !== undefined && !== correct }
  get skippedCount(): number { return this.questions.length - this.answeredCount; }
  get scorePct(): number { const t = this.questions.length; return t ? Math.round((this.correctCount / t) * 100) : 0; }
  get scoreFraction(): number { const t = this.questions.length; return t ? this.correctCount / t : 0; }
  get timedOut(): boolean { return this.timeLeft() <= 0; }

  choicesOf(q: QuizQuestion | null): string[] {
    if (!q) return [];
    const anyQ = q as any;
    if (Array.isArray(anyQ.choices) && anyQ.choices.length) return anyQ.choices;
    if (Array.isArray(anyQ.options)) return anyQ.options.map((opt: any) => (typeof opt === 'string' ? opt : opt?.text ?? ''));
    return [];
  }

  correctIndexOf(q: QuizQuestion | null): number {
    const choices = this.choicesOf(q);
    const answer = String((q as any)?.answer ?? '').trim();
    const idx = choices.findIndex((c) => String(c).trim() === answer);
    if (idx >= 0) return idx;
    const anyQ = q as any;
    if (Array.isArray(anyQ?.options)) {
      const idx2 = anyQ.options.findIndex((o: any) => o?.correct);
      if (idx2 >= 0) return idx2;
    }
    return -1;
  }

  letter(i: number): string { return String.fromCharCode(65 + i); }
  formatTime(seconds: number): string {
    const s = Math.max(0, Math.floor(seconds));
    const m = Math.floor(s / 60);
    return `${String(m).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
  }
