            <div class="flex-1 flex flex-col items-center justify-center text-center p-6">
              <ng-icon name="lucideGraduationCap" size="36" style="color: #cbd5e1;" />
              <h4 class="text-sm font-bold text-[#0f172a] mt-3">Todavía no tienes simulacros</h4>
              <p class="text-sm text-[#94a3b8] mt-1 max-w-sm">Genera el primero con el panel de la izquierda y aparecerá aquí con tu puntaje.</p>
            </div>
          } @else {
            <div class="flex-1 overflow-y-auto divide-y divide-[#f1f5f9]">
              @for (quiz of quizzes(); track quiz.id) {
                <div class="flex flex-col sm:flex-row sm:items-center gap-3 px-5 py-4 hover:bg-[#f8fafc] transition-colors">
                  <div class="flex-1 min-w-0">
                    <h4 class="text-sm font-semibold text-[#0f172a] truncate">{{ quiz.title }}</h4>
                    <div class="flex flex-wrap items-center gap-2 mt-1.5">
                      @if (quiz.subject) {
                        <span class="text-[11px] px-2 py-0.5 rounded-full bg-[#f1f5f9] text-[#475569]">{{ quiz.subject }}</span>
                      }
                      @if (quiz.difficulty) {
                        <span class="text-[11px] px-2 py-0.5 rounded-full bg-[#f1f5f9] text-[#475569]">
                          {{ quiz.difficulty === 'BEGINNER' ? 'Básico' : quiz.difficulty === 'ADVANCED' ? 'Alto' : 'Medio' }}
                        </span>
                      }
                      @if (quiz.content?.quiz?.length) {
                        <span class="text-[11px] text-[#94a3b8]">{{ quiz.content.quiz.length }} preguntas</span>
                      }
                    </div>
                  </div>

                  <div class="flex items-center gap-2 flex-shrink-0">
                    @if (quiz.completed && quiz.resultTotal !== null) {
                      <span class="text-xs font-bold px-2.5 py-1 rounded-lg" [style.background]="savedScorePct(quiz.resultScore) >= 70 ? '#dcfce7' : (savedScorePct(quiz.resultScore) >= 40 ? '#fef3c7' : '#fee2e2')"
                        [style.color]="savedScorePct(quiz.resultScore) >= 70 ? '#15803d' : (savedScorePct(quiz.resultScore) >= 40 ? '#b45309' : '#b91c1c')">
                        {{ quiz.resultCorrect }}/{{ quiz.resultTotal }} &middot; {{ savedScorePct(quiz.resultScore) }}%
                      </span>
                    }
                    <button (click)="startSaved(quiz)" class="flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-semibold transition-colors cursor-pointer"
                      [style.background]="quiz.completed ? '#f1f5f9' : '#0f766e'" [style.color]="quiz.completed ? '#475569' : '#fff'">
                      <ng-icon [name]="quiz.completed ? 'lucideRotateCcw' : 'lucidePlay'" size="14" />
                      {{ quiz.completed ? 'Repetir' : 'Comenzar' }}
                    </button>
                    <button (click)="deleteQuiz(quiz.id)" class="text-[#94a3b8] hover:text-red-500 transition-colors bg-transparent border-none cursor-pointer p-2" title="Eliminar simulacro">
                      <ng-icon name="lucideTrash2" size="16" />
                    </button>
                  </div>
                </div>
              }
            </div>
          }
        </section>
      </div>
    }

    <!-- ============================== EXAMEN ============================== -->
    @if (phase() === 'exam') {
      <div class="flex-1 flex flex-col min-h-0 overflow-hidden">
        <div class="px-4 sm:px-6 pt-4 flex-shrink-0">
          <div class="flex items-center justify-between text-xs text-[#64748b] mb-1.5">
            <span class="font-semibold text-[#0f172a]">
              Pregunta {{ currentIndex() + 1 }} de {{ questions.length }}
            </span>
            <span>{{ answeredCount }}/{{ questions.length }} respondidas</span>
          </div>
          <div class="w-full h-1.5 rounded-full bg-[#e2e8f0] overflow-hidden">
            <div class="h-full rounded-full transition-all duration-300" style="background: #0f766e;" [style.width.%]="progressPct"></div>
          </div>
        </div>

        <div class="flex-1 flex flex-col lg:flex-row gap-4 lg:gap-6 p-4 sm:p-6 overflow-hidden min-h-0">
          <!-- Pregunta -->
          <section class="flex-1 flex flex-col bg-white border border-[#e2e8f0] rounded-2xl overflow-hidden shadow-sm min-h-0">
            <div class="flex-1 overflow-y-auto p-5 sm:p-7">
              @let question = currentQuestion;
              @if (question) {
                <div class="max-w-3xl mx-auto">
                  <div class="flex items-start justify-between gap-3 mb-5">
                    <span class="text-[11px] font-bold text-[#94a3b8] uppercase tracking-widest mt-1">
                      Pregunta {{ currentIndex() + 1 }}
                    </span>
                    <button (click)="toggleFlag()" class="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold border transition-colors cursor-pointer flex-shrink-0"
                      [class]="flagged().includes(currentIndex()) ? 'border-[#fcd34d] bg-[#fef9c3] text-[#92400e]' : 'border-[#e2e8f0] bg-white text-[#64748b] hover:border-[#fcd34d] hover:text-[#92400e]'">
                      <ng-icon name="lucideFlag" size="13" />
                      {{ flagged().includes(currentIndex()) ? 'Marcada' : 'Marcar para revisar' }}
                    </button>
                  </div>

                  <h4 class="text-base sm:text-lg font-semibold text-[#0f172a] leading-relaxed quiz-q" [innerHTML]="question.question | markdown"></h4>

                  <div class="flex flex-col gap-2.5 mt-6">
                    @for (option of choicesOf(question); track $index; let oi = $index) {
                      <button (click)="selectAnswer(oi)"
                        class="w-full text-left px-4 py-3.5 rounded-xl border text-sm font-medium transition-all cursor-pointer quiz-opt"
                        [class]="answers()[currentIndex()] === oi ? 'border-[#0f766e] bg-[#f0fdfa] text-[#0f172a] shadow-sm' : 'border-[#e2e8f0] bg-white text-[#475569] hover:border-[#0f766e]/60 hover:bg-[#f8fafc]'">
                        <span class="flex items-start gap-3">
                          <span class="w-6 h-6 rounded-full border flex items-center justify-center text-xs font-bold shrink-0 mt-0.5"
                            [class]="answers()[currentIndex()] === oi ? 'border-[#0f766e] bg-[#0f766e] text-white' : 'border-[#cbd5e1] text-[#64748b]'">
                            {{ letter(oi) }}
                          </span>
                          <span class="quiz-opt-text min-w-0 flex-1 break-words" [innerHTML]="option | markdown:true"></span>
                        </span>
                      </button>
                    }
                  </div>
                </div>
              }
            </div>

            <div class="px-5 sm:px-6 py-4 border-t border-[#f1f5f9] flex items-center justify-between gap-3 flex-shrink-0 bg-white/80 backdrop-blur">
              <button (click)="prev()" [disabled]="currentIndex() === 0"
                class="flex items-center gap-1.5 px-4 py-2.5 rounded-xl text-sm font-semibold text-[#64748b] bg-white border border-[#e2e8f0] hover:bg-[#f8fafc] transition-colors cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed">
                <ng-icon name="lucideChevronLeft" size="16" />
                Anterior
              </button>

              @if (currentIndex() < questions.length - 1) {
                <button (click)="next()" class="flex items-center gap-1.5 px-5 py-2.5 rounded-xl text-sm font-bold text-white transition-all hover:brightness-110 cursor-pointer" style="background: #0f766e;">
                  Siguiente
                  <ng-icon name="lucideChevronRight" size="16" />
                </button>
              } @else {
                <button (click)="submitExam()" class="flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold text-white transition-all hover:brightness-110 cursor-pointer" style="background: #0f766e;">
                  <ng-icon name="lucideCheckCheck" size="16" />
                  Entregar simulacro
                </button>
              }
            </div>
          </section>

          <!-- Navegador -->
          <aside class="w-full lg:w-[280px] xl:w-[300px] flex-shrink-0 flex flex-col gap-4 overflow-y-auto">
            <div class="bg-white border border-[#e2e8f0] rounded-2xl p-5 shadow-sm">
              <div class="flex items-center gap-2 mb-3">
                <ng-icon name="lucideTimer" size="16" style="color: #0f766e;" />
                <h3 class="text-sm font-bold text-[#0f172a]">Tiempo restante</h3>
              </div>
              <p class="exam-clock text-3xl font-extrabold text-center py-2" [style.color]="timeCritical() ? '#b91c1c' : '#0f172a'">
                {{ remainingLabel }}
              </p>
              <div class="w-full h-1.5 rounded-full bg-[#e2e8f0] overflow-hidden mt-1">
                <div class="h-full rounded-full transition-all duration-500"
                  [style.background]="timeCritical() ? '#dc2626' : '#0f766e'"
                  [style.width.%]="timePct"></div>
              </div>
              <p class="text-[11px] text-[#94a3b8] text-center mt-2">de {{ formatTime(totalTime()) }} en total</p>
            </div>

            <div class="bg-white border border-[#e2e8f0] rounded-2xl p-5 shadow-sm">
              <h3 class="text-sm font-bold text-[#0f172a] mb-3">Preguntas</h3>
              <div class="grid grid-cols-6 gap-1.5">
                @for (item of questions; track $index; let i = $index) {
                  <button (click)="goTo(i)" class="relative w-full aspect-square rounded-lg text-xs font-bold border transition-colors cursor-pointer"
                    [class]="i === currentIndex()
                      ? 'border-[#0f766e] bg-[#0f766e] text-white'
                      : (answers()[i] !== undefined
                        ? 'border-[#a7f3d0] bg-[#ecfdf5] text-[#0f766e]'
                        : 'border-[#e2e8f0] bg-white text-[#94a3b8] hover:border-[#0f766e]/60')">
                    {{ i + 1 }}
                    @if (flagged().includes(i)) {
                      <span class="absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full border border-white" style="background: #f59e0b;"></span>
                    }
                  </button>
                }
              </div>

              <div class="mt-4 space-y-1.5 text-[11px] text-[#64748b]">
                <p class="flex items-center gap-2"><span class="w-3 h-3 rounded border border-[#a7f3d0]" style="background: #ecfdf5;"></span> Respondida</p>
                <p class="flex items-center gap-2"><span class="w-3 h-3 rounded border border-[#e2e8f0] bg-white"></span> Sin responder</p>
                <p class="flex items-center gap-2"><span class="w-3 h-3 rounded-full" style="background: #f59e0b;"></span> Marcada para revisar</p>
              </div>

              <button (click)="submitExam()" class="mt-4 w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold text-white transition-all hover:brightness-110 cursor-pointer" style="background: #0f766e;">
                <ng-icon name="lucideCheckCheck" size="16" />
                Entregar simulacro
              </button>
              @if (skippedCount > 0) {
                <p class="text-[11px] text-[#b45309] text-center mt-2">
                  Tienes {{ skippedCount }} pregunta{{ skippedCount === 1 ? '' : 's' }} sin responder.
                </p>
              }
            </div>
          </aside>
        </div>
      </div>
    }

    <!-- ============================== RESULTADOS ============================== -->
    @if (phase() === 'results') {
      <div class="flex-1 overflow-y-auto p-4 sm:p-6">
        <div class="max-w-3xl mx-auto space-y-4">
          <div class="bg-white border border-[#e2e8f0] rounded-2xl p-6 shadow-sm text-center">
            <div class="w-28 h-28 mx-auto rounded-full flex items-center justify-center" [style.background]="scoreTone.background">
              <div class="text-center">
                <p class="text-3xl font-extrabold" [style.color]="scoreTone.color">{{ scorePct }}%</p>
                <p class="text-[11px] font-semibold" [style.color]="scoreTone.color">{{ correctCount }}/{{ questions.length }}</p>
              </div>
            </div>

            <h3 class="text-xl sm:text-2xl font-bold text-[#0f172a] mt-4">{{ resultTitle }}</h3>
            <p class="text-sm text-[#64748b] mt-1">
              @if (timedOut) {
                Se agotó el tiempo: respondiste {{ answeredCount }} de {{ questions.length }} preguntas.
              } @else {
                Terminaste en {{ elapsedLabel }} de {{ formatTime(totalTime()) }} disponibles.
              }
            </p>

            <div class="grid grid-cols-2 sm:grid-cols-4 gap-2.5 mt-5">
              <div class="rounded-xl border border-[#e2e8f0] p-3">
                <p class="text-[11px] font-semibold text-[#94a3b8] uppercase tracking-wider">Correctas</p>
                <p class="text-lg font-bold" style="color: #15803d;">{{ correctCount }}</p>
              </div>
              <div class="rounded-xl border border-[#e2e8f0] p-3">
                <p class="text-[11px] font-semibold text-[#94a3b8] uppercase tracking-wider">Incorrectas</p>
                <p class="text-lg font-bold" style="color: #b91c1c;">{{ wrongCount }}</p>
              </div>
              <div class="rounded-xl border border-[#e2e8f0] p-3">
                <p class="text-[11px] font-semibold text-[#94a3b8] uppercase tracking-wider">Sin responder</p>
                <p class="text-lg font-bold text-[#475569]">{{ skippedCount }}</p>
              </div>
              <div class="rounded-xl border border-[#e2e8f0] p-3">
                <p class="text-[11px] font-semibold text-[#94a3b8] uppercase tracking-wider">Tiempo usado</p>
                <p class="text-lg font-bold text-[#0f172a]">{{ elapsedLabel }}</p>
              </div>
            </div>

            <div class="flex flex-wrap items-center justify-center gap-2.5 mt-5">
              @if (savingResult()) {
                <span class="flex items-center gap-2 text-xs font-semibold text-[#64748b]">
                  <span class="w-3.5 h-3.5 border-2 border-[#cbd5e1] border-t-[#0f766e] rounded-full animate-spin"></span>
                  Guardando resultado...
                </span>
              } @else if (savedResult()) {
                <span class="flex items-center gap-1.5 text-xs font-semibold" style="color: #15803d;">
                  <ng-icon name="lucideCheckCircle2" size="14" />
                  Resultado guardado
                </span>
              } @else if (saveError()) {
                <button (click)="retrySave()" class="flex items-center gap-1.5 text-xs font-semibold text-[#b45309] hover:underline cursor-pointer">
                  <ng-icon name="lucideAlertCircle" size="14" />
                  No se pudo guardar. Reintentar
                </button>
              }

              <button (click)="retakeExam()" class="flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-semibold text-[#475569] bg-white border border-[#e2e8f0] hover:bg-[#f8fafc] transition-colors cursor-pointer">
                <ng-icon name="lucideRotateCcw" size="15" />
                Repetir
              </button>
              <button (click)="backToList()" class="px-5 py-2.5 rounded-xl text-sm font-bold text-white transition-all hover:brightness-110 cursor-pointer" style="background: #0f766e;">
                Volver a mis simulacros
              </button>
            </div>
          </div>

          <div class="bg-white border border-[#e2e8f0] rounded-2xl overflow-hidden shadow-sm">
            <div class="px-5 py-4 border-b border-[#f1f5f9] flex items-center gap-2.5">
              <ng-icon name="lucideBookOpen" size="18" style="color: #0f766e;" />
              <h3 class="text-sm font-bold text-[#0f172a]">Revisión de respuestas</h3>
            </div>

            @for (question of questions; track $index; let i = $index) {
              <div class="px-4 sm:px-5 py-4 border-b border-[#f1f5f9] last:border-b-0">
                <div class="flex items-start gap-3">
                  <span class="w-6 h-6 rounded-full text-xs font-bold flex items-center justify-center shrink-0 mt-0.5"
                    [class]="isSkipped(i) ? 'bg-[#f1f5f9] text-[#64748b]' : (isCorrectAnswer(i) ? 'bg-[#dcfce7] text-[#15803d]' : 'bg-[#fee2e2] text-[#b91c1c]')">
                    {{ i + 1 }}
                  </span>

                  <div class="min-w-0 flex-1">
                    <div class="text-sm font-semibold text-[#0f172a] quiz-q" [innerHTML]="question.question | markdown"></div>

                    <div class="mt-2 space-y-1 text-sm">
                      <p class="flex items-start gap-2">
                        <span class="text-[#94a3b8] shrink-0">Tu respuesta:</span>
                        <span class="min-w-0"
                          [style.color]="isSkipped(i) ? '#94a3b8' : (isCorrectAnswer(i) ? '#15803d' : '#b91c1c')">
                          {{ userAnswerText(i) }}
                        </span>
                      </p>
                      @if (!isCorrectAnswer(i)) {
                        <p class="flex items-start gap-2">
                          <span class="text-[#94a3b8] shrink-0">Correcta:</span>
                          <span class="min-w-0" style="color: #15803d;">{{ correctAnswerText(question) }}</span>
                        </p>
                      }
                    </div>

                    @if (question.explanation) {
                      <div class="mt-2.5 text-sm text-[#475569] leading-relaxed quiz-explain" [innerHTML]="question.explanation | markdown:true"></div>
                    }

                    @if (explanations()[i]) {
                      <div class="mt-3 p-3.5 rounded-xl text-sm leading-relaxed" style="background: #eef2ff; color: #3730a3;" [innerHTML]="explanations()[i] | markdown:true"></div>
                    } @else {
                      <button (click)="explainReview(i)" [disabled]="loadingExplanation() !== null"
                        class="mt-3 inline-flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs font-semibold transition-all cursor-pointer disabled:opacity-50 disabled:cursor-default"
                        style="background: #eef2ff; color: #4f46e5; border: 1px solid #c7d2fe;">
                        @if (loadingExplanation() === i) {
                          <span class="w-3.5 h-3.5 border-2 border-[#4f46e5]/30 border-t-[#4f46e5] rounded-full animate-spin"></span>
                          Explicando...
                        } @else {
                          <ng-icon name="lucideLightbulb" size="14" />
                          Explicación IA
                        }
                      </button>
                    }
                  </div>
                </div>
              </div>
            }
          </div>
        </div>
      </div>
    }
  </main>
</div>
