```ts
uploadDocument(file: File, onProgress?: (pct: number, label: string) => void): Observable<string> {
  const total = Math.max(1, Math.ceil(file.size / CHUNK_BYTES));
  let uploadId: string | null = null;
  const indexes = Array.from({length: total}, (_, i) => i);
  return from(indexes).pipe(
    concatMap((index) => {
      const blob = file.slice(index * CHUNK_BYTES, Math.min((index + 1) * CHUNK_BYTES, file.size));
      const form = new FormData();
      form.append('file', blob, file.name);
      const params = buildQuery({ uploadId: uploadId || undefined, index, total, filename: file.name, mimetype: file.type || 'application/pdf' });
      return this.http.post<{uploadId: string; received: number; total: number}>(`${API}/ai/uploads/chunk${params}`, form).pipe(
        tap((res) => { uploadId = res.uploadId; onProgress?.(Math.round(((index + 1) / total) * 100), `Subiendo ${index+1}/${total}…`); })
      );
    }),
    map(() => uploadId as string),
  );
}
```
