import { DocumentTextService } from '../document-text.service';
import { CHUNK_SIZE_BYTES, MAX_CHUNKS, UploadsRepository, UploadSession } from './uploads.repository';

export interface UploadProgress { uploadId: string; received: number; total: number; }

