  constructor(private readonly repo: UploadsRepository, private readonly documents: DocumentTextService) {}

  async saveChunk(userId, { uploadId, index, total, filename, mimetype, buffer }): Promise<UploadProgress> {
    if (!buffer?.length) throw new BadRequestException('El trozo llegó vacío.');
    if (buffer.length > CHUNK_SIZE_BYTES * 1.5) throw new BadRequestException('El trozo es demasiado grande.');
    const totalChunks = Math.min(MAX_CHUNKS, Math.max(1, Number(total)||1));
