/** Tamaño de cada trozo: debe quedar por debajo del límite de cuerpo del backend. */
const UPLOAD_CHUNK_BYTES = 3 * 1024 * 1024;

/**
 * Sube el documento por partes (para superar el límite de ~4.5 MB por petición)
 * y devuelve el id de la subida ya completa.
 */
uploadDocumentInChunks(file: File, onProgress?: (percent: number) => void): Observable<string> {
  const total = Math.max(1, Math.ceil(file.size / UPLOAD_CHUNK_BYTES));
  let uploadId: string | null = null;
  const indexes = Array.from({ length: total }, (_, i) => i);
  return from(indexes).pipe(
    concatMap((index) => {
      const start = index * UPLOAD_CHUNK_BYTES;
      const blob = file.slice(start, Math.min(start + UPLOAD_CHUNK_BYTES, file.size));
      const form = new FormData();
      form.append('file', blob, file.name);
      const query = buildQuery({ uploadId: uploadId || undefined, index, total, filename: file.name, mimetype: file.type || 'application/octet-stream' });
      return this.http.post<{ uploadId: string }>(`${API}/ai/uploads/chunk${query}`, form).pipe(
        tap((res) => {
          uploadId = res.uploadId;
          onProgress?.(Math.round(((index + 1) / total) * 100));
        }),
      );
    }),
    map(() => uploadId as string),
    filter((id) => !!id),  // not needed
  );
}
